import{_ as o,o as d,c as i,ag as t}from"./chunks/framework.DezAaKNx.js";const g=JSON.parse('{"title":"Changelog","description":"","frontmatter":{},"headers":[],"relativePath":"changelog.md","filePath":"changelog.md"}'),a={name:"changelog.md"};function c(r,e,l,n,s,h){return d(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h1><h1 id="changelog-1" tabindex="-1">Changelog <a class="header-anchor" href="#changelog-1" aria-label="Permalink to &quot;Changelog&quot;">​</a></h1><p>All notable changes to this project will be documented in this file.</p><p>The format is based on <a href="https://keepachangelog.com/en/1.1.0/" target="_blank" rel="noreferrer">Keep a Changelog</a>, and this project adheres to <a href="https://semver.org/spec/v2.0.0.html" target="_blank" rel="noreferrer">Semantic Versioning</a>.</p><h2 id="unreleased" tabindex="-1"><a href="https://github.com/jsuyog2/postgis/compare/v1.2.0...HEAD" target="_blank" rel="noreferrer">Unreleased</a> <a class="header-anchor" href="#unreleased" aria-label="Permalink to &quot;[Unreleased]&quot;">​</a></h2><h2 id="_1-2-0-2026-03-10" tabindex="-1"><a href="https://github.com/jsuyog2/postgis/compare/v1.0.6...v1.2.0" target="_blank" rel="noreferrer">1.2.0</a> - 2026-03-10 <a class="header-anchor" href="#_1-2-0-2026-03-10" aria-label="Permalink to &quot;[1.2.0] - 2026-03-10&quot;">​</a></h2><h3 id="added" tabindex="-1">Added <a class="header-anchor" href="#added" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li>Full <strong>TypeScript</strong> support — all source files migrated to <code>src/</code> with strict typings</li><li><strong>Dual ESM + CJS</strong> build output via <code>tsup</code> — tree-shakable and bundler-friendly</li><li><code>src/types/index.ts</code> — exported interfaces for all method options and return types</li><li><code>src/utils/validation.ts</code> — shared <code>parsePoint()</code> helper and typed assertion guards</li><li><code>src/utils/logger.ts</code> — structured debug logger (enabled via <code>POSTGIS_DEBUG=true</code>)</li><li><strong>Vitest</strong> test runner replacing Jest — same API, native ESM support, faster execution</li><li><code>vitest.config.ts</code> with v8 coverage provider</li><li><code>tsup.config.ts</code> for production-ready dual bundle generation</li><li><code>.prettierrc</code> — Prettier code formatting config</li><li><code>.editorconfig</code> — cross-editor indentation and line ending consistency</li><li><code>.npmignore</code> — reduces install footprint by excluding <code>src/</code>, tests, and docs</li><li><code>LICENSE</code> file (MIT)</li><li><code>CONTRIBUTING.md</code> — fork, branch, commit, and PR guidelines</li><li><code>CODE_OF_CONDUCT.md</code> — Contributor Covenant 2.1</li><li><code>SECURITY.md</code> — private vulnerability disclosure process and SQL injection warning</li><li><code>CHANGELOG.md</code> — this file</li><li>GitHub Actions <code>ci.yml</code> — lint + test + build on every push/PR</li><li>GitHub Actions <code>docs.yml</code> — VitePress docs auto-deploy to GitHub Pages</li><li>GitHub Actions <code>publish.yml</code> — npm + GitHub Packages publish on release</li><li>VitePress documentation site under <code>docs/</code></li><li><code>examples/</code> directory with basic usage, GeoJSON export, and MVT server examples</li><li>Expanded npm keywords for better discoverability</li></ul><h3 id="changed" tabindex="-1">Changed <a class="header-anchor" href="#changed" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li><code>intersect_point</code>, <code>nearest</code>, and <code>transform_point</code> now throw a descriptive <code>Error</code> with message <code>&quot;Invalid point format ...&quot;</code> instead of crashing with a <code>TypeError</code></li><li><code>_executeQuery</code> return is now <code>res.rows ?? []</code> — no more fragile fallback chain</li><li><code>package.json</code> <code>license</code> corrected from <code>ISC</code> → <code>MIT</code></li><li>Updated <code>package.json</code> with <code>exports</code>, <code>types</code>, <code>sideEffects: false</code>, <code>files</code> whitelist, <code>engines</code>, <code>funding</code>, and expanded <code>keywords</code></li><li><code>eslint.config.mjs</code> upgraded to include <code>typescript-eslint</code> rules</li></ul><h3 id="fixed" tabindex="-1">Fixed <a class="header-anchor" href="#fixed" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>License mismatch between <code>package.json</code> (ISC) and README (MIT) — now consistently MIT</li></ul><h2 id="_1-0-6-2025-01-15" tabindex="-1"><a href="https://github.com/jsuyog2/postgis/releases/tag/v1.0.6" target="_blank" rel="noreferrer">1.0.6</a> - 2025-01-15 <a class="header-anchor" href="#_1-0-6-2025-01-15" aria-label="Permalink to &quot;[1.0.6] - 2025-01-15&quot;">​</a></h2><h3 id="added-1" tabindex="-1">Added <a class="header-anchor" href="#added-1" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li>Initial public release</li><li><code>list_tables</code>, <code>list_columns</code>, <code>query_table</code></li><li><code>bbox</code>, <code>centroid</code></li><li><code>intersect_feature</code>, <code>intersect_point</code></li><li><code>geojson</code>, <code>geobuf</code>, <code>mvt</code></li><li><code>nearest</code>, <code>transform_point</code></li><li>Jest test suite with mocked pg.Client</li></ul>',15)])])}const p=o(a,[["render",c]]);export{g as __pageData,p as default};
